/// <summary>
/// Batch service class for Pack change repricing sales orders
/// </summary>
public class METPackChangeSORepricingService extends SysOperationServiceBase
{            
}

Method.Source:
/// <summary>
/// Processes sales orders that require repricing due to pack changes.
/// </summary>
/// <param name="_contract">
/// The <see cref="METPackChangeSORepricingContract"/> containing the item ID parameter for filtering sales lines.
/// </param>
public void process(METPackChangeSORepricingContract _contract)
{
    SalesTable                  salesTable;
    METSalesTable               metSalesTable, metSalesTableUpdate;
    SalesLine                   salesLine;
    METSalesLine                metSalesLine, metSalesLineUpdate;
    InventTable                 inventTable;
    EcoResProduct               ecoResProduct;
    Set                         metSalesTableSet = new Set(Types::Int64);
    SetEnumerator               metSalesTableSetEnumerator;
    ItemId                      itemId = _contract.parmItemId();

    ttsbegin;
    while select RecId from salesTable
            where salesTable.SalesStatus == SalesStatus::Backorder
            join metSalesTable
            where metSalesTable.SalesTable == salesTable.RecId
                && metSalesTable.OrderProcessingStatus == METSalesOrderProcessingStatus::RepriceRequired
                join salesLine
                where salesLine.SalesId == salesTable.SalesId
                && salesLine.ItemId == itemId
                && salesLine.SalesStatus != SalesStatus::Canceled
                    join RecId, ItemId from inventTable
                    where InventTable.ItemId == SalesLine.ItemId
                        join RecId from ecoResProduct
                        where ecoResProduct.RecId == inventTable.Product
                            join RecId from metSalesLine
                            where metSalesLine.SalesLine == salesLine.RecId
                            && metSalesLine.OrderExtractStatus == METOrderExtractStatus::Open
                            && metSalesLine.DelayPricing == METDelayPricing::PackChange
    {

        metSalesTableUpdate = METSalesTable::findBySalesTable(SalesTable.RecId, true);
        metSalesTableUpdate.OrderProcessingStatus = METSalesOrderProcessingStatus::ReadyForPricing;
        metSalesTableUpdate.update();

        metSalesLineUpdate = METSalesLine::find(salesLine.RecId, true);
        metSalesLineUpdate.DelayPricing = METDelayPricing::None;
        metSalesLineUpdate.update();

        if (!metSalesTableSet.in(metSalesTable.SalesTable))
        {
            metSalesTableSet.add(metSalesTable.SalesTable);
        }
    }
    ttscommit;

    metSalesTableSetEnumerator = metSalesTableSet.getEnumerator();
    while (metSalesTableSetEnumerator.moveNext())
    {
        this.updateMetSalesTableDelayPricing(metSalesTableSetEnumerator.current());                       
    }
    Info(strFmt("@MET:PackChangeSORepricingJobCompletion", itemId));
}

/// <summary>
/// Updates the DelayPricing field in the related METSalesTable record based on the value of DelayPricing in the current and other METSalesLine records.
/// </summary>
public void updateMetSalesTableDelayPricing(RefRecId _salesTableRecId)
{
    SalesTable      salesTable;
    SalesLine       salesLine;
    METSalesTable   metSalesTable;
    METSalesLine    metSalesLine;

    select firstonly RecId from metSalesLine
            where metSalesLine.DelayPricing == METDelayPricing::PackChange
            join salesLine
                where salesLine.RecId == metSalesLine.SalesLine
            join salesTable
                where salesLine.SalesId == salesTable.SalesId
                && salesTable.RecId == _salesTableRecId;

    if(!metSalesLine.RecId)
    {
        metSalesTable =  METSalesTable::findBySalesTable(_salesTableRecId, true);

        ttsbegin;                    
        metSalesTable.DelayPricing = METDelayPricing::None;
        metSalesTable.update();
        ttscommit;
    }                      
}
